import { useState } from "react";
import ComUsage from "./ComUsage";
import GenStats from "./GenStats";

function App() {
  const [page, setPage] = useState("usage");

  return (
    <div>
      <header style={{
        background: "#222",
        color: "white",
        padding: "15px",
        textAlign: "center"
      }}>
        <h1 style={{ margin: 0 }}>Pokémon Analytics Dashboard</h1>

        <nav style={{ marginTop: "10px" }}>
          <button
            onClick={() => setPage("usage")}
            style={navButtonStyle(page === "usage")}
          >
            Usage (Line)
          </button><button
            onClick={() => setPage("stats")}
            style={navButtonStyle(page === "stats")}
          >
            Stats (Bar)
          </button>


        </nav>
      </header>

      <main style={{ padding: "20px" }}>
        {page === "usage" && <ComUsage />}
        {page === "stats" && <GenStats />}

      </main>
    </div>
  );
}

const navButtonStyle = (active) => ({
  margin: "0 10px",
  padding: "8px 15px",
  background: active ? "#4CAF50" : "#555",
  color: "white",
  border: "none",
  cursor: "pointer",
  borderRadius: "5px"
});

export default App;
